// KYB Information Validation and Scoring
const kybData = items[0].json.kybInformation;
const applicationData = items[0].json.applicationData;

if (!kybData) {
  return [{
    json: {
      loanApplicationId: items[0].json.loanApplicationId,
      status: 'failed',
      error: 'No KYB information provided'
    }
  }];
}

// Business validation rules
const validationResults = {
  businessNameValid: kybData.business_name && kybData.business_name.length >= 2,
  registrationValid: kybData.business_registration_no && kybData.business_registration_no.length > 0,
  taxIdValid: kybData.tax_identification_number && kybData.tax_identification_number.length > 0,
  yearsInOperationValid: kybData.years_in_operation >= 1,
  directorsValid: kybData.directors_information && kybData.directors_information.length > 0,
  beneficialOwnersValid: kybData.beneficial_owners && kybData.beneficial_owners.length > 0
};

// Calculate KYB score
const totalChecks = Object.keys(validationResults).length;
const passedChecks = Object.values(validationResults).filter(Boolean).length;
const kybScore = (passedChecks / totalChecks) * 100;

// Risk assessment based on business details
const riskFactors = [];
if (kybData.years_in_operation < 2) {
  riskFactors.push('Limited operating history');
}
if (!kybData.annual_revenue || kybData.annual_revenue < 50000) {
  riskFactors.push('Low annual revenue');
}
if (kybData.industry_type && ['gambling', 'crypto', 'adult'].includes(kybData.industry_type.toLowerCase())) {
  riskFactors.push('High-risk industry');
}

// Determine risk level
let riskLevel = 'low';
if (riskFactors.length > 2 || kybScore < 70) {
  riskLevel = 'high';
} else if (riskFactors.length > 0 || kybScore < 85) {
  riskLevel = 'medium';
}

return [{
  json: {
    loanApplicationId: items[0].json.loanApplicationId,
    kybValidation: {
      score: kybScore,
      validationResults: validationResults,
      riskLevel: riskLevel,
      riskFactors: riskFactors
    },
    processedKybData: {
      businessName: kybData.business_name,
      businessType: kybData.business_type,
      industryType: kybData.industry_type,
      yearsInOperation: kybData.years_in_operation,
      annualRevenue: kybData.annual_revenue || 0,
      monthlyRevenue: kybData.monthly_revenue || 0,
      numberOfEmployees: kybData.number_of_employees || 0
    },
    status: kybScore >= 60 ? 'kyb_validated' : 'kyb_failed'
  }
}];

// Financial Statement Analysis
const financialStatements = items[0].json.financialStatements;
const applicationData = items[0].json.applicationData;

if (!financialStatements || financialStatements.length === 0) {
  return [{
    json: {
      loanApplicationId: items[0].json.loanApplicationId,
      status: 'failed',
      error: 'No financial statements provided'
    }
  }];
}

// Analyze each financial statement
const analyzedStatements = financialStatements.map(statement => {
  const periodDays = Math.ceil((new Date(statement.statement_period_to) - new Date(statement.statement_period_from)) / (1000 * 60 * 60 * 24));
  const avgDailyBalance = statement.average_balance || ((statement.opening_balance + statement.closing_balance) / 2);
  const turnoverRatio = statement.total_credits > 0 ? statement.total_debits / statement.total_credits : 0;
  const cashFlowStability = Math.abs(statement.closing_balance - statement.opening_balance) / Math.max(statement.opening_balance, 1);

  // Calculate financial health indicators
  const healthScore = Math.min(100, Math.max(0, 
    (avgDailyBalance / 1000 * 10) + // Balance score
    (statement.total_credits / 10000 * 20) + // Credit activity score
    (statement.transaction_count / 50 * 15) + // Activity frequency score
    ((1 - Math.min(turnoverRatio, 2)) * 25) + // Turnover health score
    ((1 - Math.min(cashFlowStability, 1)) * 30) // Stability score
  ));

  return {
    type: statement.type,
    providerName: statement.provider_name,
    avgDailyBalance: avgDailyBalance,
    totalCredits: statement.total_credits,
    totalDebits: statement.total_debits,
    transactionCount: statement.transaction_count,
    healthScore: Math.round(healthScore),
    turnoverRatio: Math.round(turnoverRatio * 100) / 100,
    cashFlowStability: Math.round(cashFlowStability * 100) / 100,
    periodDays: periodDays
  };
});

// Calculate overall financial health
const avgHealthScore = analyzedStatements.reduce((sum, stmt) => sum + stmt.healthScore, 0) / analyzedStatements.length;
const totalCredits = analyzedStatements.reduce((sum, stmt) => sum + stmt.totalCredits, 0);
const totalAvgBalance = analyzedStatements.reduce((sum, stmt) => sum + stmt.avgDailyBalance, 0) / analyzedStatements.length;

// Determine creditworthiness
let creditRating = 'poor';
if (avgHealthScore >= 80) {
  creditRating = 'excellent';
} else if (avgHealthScore >= 65) {
  creditRating = 'good';
} else if (avgHealthScore >= 50) {
  creditRating = 'fair';
}

// Risk indicators
const riskIndicators = [];
if (totalAvgBalance < 10000) {
  riskIndicators.push('Low average balance');
}
if (avgHealthScore < 50) {
  riskIndicators.push('Poor financial health');
}
const highTurnoverCount = analyzedStatements.filter(stmt => stmt.turnoverRatio > 1.5).length;
if (highTurnoverCount > 0) {
  riskIndicators.push('High turnover ratio detected');
}

return [{
  json: {
    loanApplicationId: items[0].json.loanApplicationId,
    financialAnalysis: {
      overallHealthScore: Math.round(avgHealthScore),
      creditRating: creditRating,
      totalMonthlyCredits: Math.round(totalCredits),
      averageBalance: Math.round(totalAvgBalance),
      riskIndicators: riskIndicators,
      statementAnalysis: analyzedStatements
    },
    status: avgHealthScore >= 40 ? 'financial_analyzed' : 'financial_insufficient'
  }
}];

// Document Processing (Invoice/Contract)
const documentPath = items[0].json.documentPath;
const applicationData = items[0].json.applicationData;

if (!documentPath) {
  return [{
    json: {
      loanApplicationId: items[0].json.loanApplicationId,
      status: 'failed',
      error: 'No document provided for processing'
    }
  }];
}

// Simulate document extraction (in real implementation, this would use OCR/AI)
const extractedData = {
  documentType: applicationData.source === 'invoice' ? 'invoice' : 'contract',
  amount: applicationData.requested_amount,
  currency: applicationData.currency || 'USD',
  issueDate: new Date().toISOString(),
  dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // 30 days from now
  clientName: 'Extracted Client Name',
  description: applicationData.purpose || 'Document-based loan request'
};

// Validate document data
const validationResults = {
  amountValid: extractedData.amount > 0,
  dateValid: new Date(extractedData.issueDate) <= new Date(),
  dueDateValid: new Date(extractedData.dueDate) > new Date(),
  clientValid: extractedData.clientName && extractedData.clientName.length > 0
};

const validationScore = Object.values(validationResults).filter(Boolean).length / Object.keys(validationResults).length * 100;

return [{
  json: {
    loanApplicationId: items[0].json.loanApplicationId,
    documentExtraction: {
      extractedData: extractedData,
      validationResults: validationResults,
      validationScore: Math.round(validationScore)
    },
    status: validationScore >= 75 ? 'document_processed' : 'document_invalid'
  }
}];

// Financial Institution Matching Logic
const institutions = items[0].json.data || [];
const applicationData = items[1].json.applicationData;
const kybValidation = items[1].json.kybValidation;
const financialAnalysis = items[1].json.financialAnalysis;
const loanApplicationId = items[1].json.loanApplicationId;

if (institutions.length === 0) {
  return [{
    json: {
      loanApplicationId: loanApplicationId,
      status: 'failed',
      error: 'No financial institutions available for matching'
    }
  }];
}

// Scoring criteria weights
const weights = {
  amountMatch: 0.25,
  riskProfile: 0.30,
  industryMatch: 0.20,
  interestRate: 0.15,
  processingFee: 0.10
};

const requestedAmount = applicationData.requested_amount;
const businessType = kybValidation?.processedKybData?.businessType || 'general';
const industryType = kybValidation?.processedKybData?.industryType || 'general';
const overallRiskLevel = kybValidation?.riskLevel || 'medium';
const creditRating = financialAnalysis?.creditRating || 'fair';

// Score each institution
const scoredInstitutions = institutions.map(institution => {
  let score = 0;
  const matchReasons = [];

  // Amount matching
  const amountFits = requestedAmount >= (institution.min_invoice_amount || 0) && 
                    requestedAmount <= (institution.max_invoice_amount || Infinity);
  if (amountFits) {
    score += weights.amountMatch * 100;
    matchReasons.push('Amount within acceptable range');
  }

  // Risk profile matching
  const riskScore = {
    'low': { 'excellent': 100, 'good': 90, 'fair': 70, 'poor': 40 },
    'medium': { 'excellent': 90, 'good': 85, 'fair': 75, 'poor': 50 },
    'high': { 'excellent': 70, 'good': 65, 'fair': 60, 'poor': 55 }
  };

  const riskMatch = riskScore[overallRiskLevel]?.[creditRating] || 50;
  score += weights.riskProfile * riskMatch;
  if (riskMatch > 70) {
    matchReasons.push('Good risk profile match');
  }

  // Industry matching (simplified)
  const industryMatch = industryType.toLowerCase().includes('tech') || 
                       industryType.toLowerCase().includes('service') ? 80 : 70;
  score += weights.industryMatch * industryMatch;

  // Interest rate preference (lower is better)
  const avgRate = (institution.interest_rate_min + institution.interest_rate_max) / 2;
  const rateScore = Math.max(0, 100 - (avgRate * 10)); // Normalize rate to 0-100 scale
  score += weights.interestRate * rateScore;
  if (avgRate < 15) {
    matchReasons.push('Competitive interest rates');
  }

  // Processing fee (lower is better)
  const feeScore = Math.max(0, 100 - (institution.processing_fee / 100));
  score += weights.processingFee * feeScore;

  // Calculate estimated terms
  const estimatedRate = avgRate + (overallRiskLevel === 'high' ? 2 : overallRiskLevel === 'medium' ? 1 : 0);
  const estimatedFees = institution.processing_fee + (requestedAmount * 0.005); // 0.5% of amount

  return {
    institutionId: institution.id,
    institutionName: institution.name,
    institutionCode: institution.code,
    matchScore: Math.round(score),
    matchReasons: matchReasons,
    estimatedRate: Math.round(estimatedRate * 100) / 100,
    estimatedFees: Math.round(estimatedFees * 100) / 100,
    amountRange: {
      min: institution.min_invoice_amount,
      max: institution.max_invoice_amount
    },
    processingTime: institution.terms_days || 30
  };
}).filter(inst => inst.matchScore > 30).sort((a, b) => b.matchScore - a.matchScore);

// Select top 5 matches
const topMatches = scoredInstitutions.slice(0, 5);
const recommendedInstitution = topMatches.length > 0 ? topMatches[0] : null;

// Overall risk assessment
const overallRiskScore = Math.round(
  (kybValidation?.score || 50) * 0.4 + 
  (financialAnalysis?.overallHealthScore || 50) * 0.6
);

const riskAssessment = {
  overallRiskScore: overallRiskScore,
  riskLevel: overallRiskScore >= 80 ? 'low' : overallRiskScore >= 60 ? 'medium' : 'high',
  creditworthinessScore: financialAnalysis?.overallHealthScore || 50,
  businessRiskFactors: [
    ...(kybValidation?.riskFactors || []),
    ...(financialAnalysis?.riskIndicators || [])
  ],
  recommendations: [
    overallRiskScore >= 70 ? 'Approved for standard terms' : 'Consider enhanced due diligence',
    topMatches.length > 0 ? `Matched with ${topMatches.length} suitable institutions` : 'Limited institutional matches'
  ]
};

return [{
  json: {
    loanApplicationId: loanApplicationId,
    matchedInstitutions: topMatches,
    recommendedInstitution: recommendedInstitution,
    riskAssessment: riskAssessment,
    processedData: {
      kybValidation: kybValidation,
      financialAnalysis: financialAnalysis,
      institutionMatching: {
        totalMatches: topMatches.length,
        topMatchScore: recommendedInstitution?.matchScore || 0
      }
    },
    status: 'completed'
  }
}];
